<template><ForgeDialog title="Token generator" description="Generate a cryptographically secure random token locally." eyebrow="WORKSPACE / SECURITY" wide @close="emit('close')"><div class="token-panel"><label>Length <input v-model.number="length" type="number" min="1" max="512" /></label><div class="token-options"><label><input v-model="upper" type="checkbox" /> Uppercase</label><label><input v-model="lower" type="checkbox" /> Lowercase</label><label><input v-model="numbers" type="checkbox" /> Numbers</label><label><input v-model="symbols" type="checkbox" /> Symbols</label></div><textarea :value="token" readonly rows="4" /><div class="detail-actions"><button class="action-button" @click="generate">Refresh</button><button class="primary-button" @click="copy">Copy token</button></div><p v-if="error" class="forge-alert forge-alert--error">{{ error }}</p></div></ForgeDialog></template>
<script setup lang="ts">
import { ref, watch } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import { clipboard } from '@/util/NodeFn'
import { generateToken } from '../tools/token'
const emit=defineEmits<{close:[]}>(); const length=ref(64); const upper=ref(true); const lower=ref(true); const numbers=ref(true); const symbols=ref(false); const token=ref(''); const error=ref(''); const generate=()=>{let chars='';if(upper.value)chars+='ABCDEFGHIJKLMNOPQRSTUVWXYZ';if(lower.value)chars+='abcdefghijklmnopqrstuvwxyz';if(numbers.value)chars+='0123456789';if(symbols.value)chars+='.,;:!?./-"\'#{([-|\\@)]=}*+';try{token.value=generateToken(length.value,chars);error.value=''}catch(e){error.value=e instanceof Error?e.message:String(e);token.value=''}}; const copy=()=>clipboard.writeText(token.value); watch([length,upper,lower,numbers,symbols],generate,{immediate:true})
</script>
<style scoped>.token-panel{display:grid;gap:14px}.token-panel label{display:grid;gap:7px;color:var(--pqt-text-muted);font-size:11px}.token-panel>label input{padding:9px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.token-options{display:grid;grid-template-columns:1fr 1fr;gap:8px}.token-options label{display:block;padding:9px;border:1px solid var(--pqt-border);border-radius:6px}.token-panel textarea{width:100%;padding:12px;resize:none;color:#b3d7ce;background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:13px var(--pqt-font-mono);word-break:break-all}</style>
